-- Remove external scheduler parameters from current pipeline definitions.
UPDATE CFG_PIPELINES
SET PIPELINE_PARAMETERS = json_remove(PIPELINE_PARAMETERS, '$.CATCHUP', '$.DEPENDS_ON_PAST', '$.EMAIL_ON_FAILURE', '$.RETRIES', '$.RETRY_DELAY_MINUTES')
WHERE PIPELINE_PARAMETERS IS NOT NULL AND (json_type(PIPELINE_PARAMETERS, '$.CATCHUP') IS NOT NULL OR json_type(PIPELINE_PARAMETERS, '$.DEPENDS_ON_PAST') IS NOT NULL OR json_type(PIPELINE_PARAMETERS, '$.EMAIL_ON_FAILURE') IS NOT NULL OR json_type(PIPELINE_PARAMETERS, '$.RETRIES') IS NOT NULL OR json_type(PIPELINE_PARAMETERS, '$.RETRY_DELAY_MINUTES') IS NOT NULL);
